// ประตูกันคนนอก: tunnel เปิด webhook นี้สู่อินเทอร์เน็ต จึงต้องมี token
// หมายเหตุ: ใน Code node ห้ามใช้ process.env (sandbox) — ใช้ $env ของ n8n แทน
const j = $input.first().json || {};
const h = j.headers || {};
const auth = String(h.authorization || h.Authorization || '');
const secret = ($env && $env.CRON_SECRET) ? String($env.CRON_SECRET) : '';
const expected = 'Bearer ' + secret;
const bodyToken = String((j.body && j.body.token) || '');
const ok = !!secret && (auth === expected || bodyToken === secret);
if (!ok) {
  throw new Error('UNAUTHORIZED: webhook นี้ต้องมี Authorization: Bearer $CRON_SECRET หรือ body.token');
}
return $input.all();

// อ่านผลลัพธ์จาก local-runner (JSON บรรทัดสุดท้ายของสคริปต์) แล้วสรุปให้เป็นฟิลด์เดียว
// พร้อมตั้งค่าช่วงวันของรายงานผู้สมัคร (จาก body ของ webhook ถ้ามี ไม่งั้นใช้ค่าเริ่มต้น)
const pickNode = (names) => {
  for (const n of names) { try { const j = $(n).first().json; if (j) return j; } catch (e) {} }
  return {};
};
const src = pickNode(['ตรวจสิทธิ์ (token)']);
const req = (src && src.body) || {};

const j = $input.first().json || {};
let r = null;
if (j && typeof j.ok !== 'undefined') r = j;                 // มาจาก local-runner โดยตรง
else {                                                       // เผื่อมาจาก stdout ของคำสั่งอื่น
  const tail = String((j && j.stdout) || '').trim().split('\n').filter(Boolean).pop() || '';
  try { r = JSON.parse(tail); } catch (e) { r = null; }
}
if (!r || typeof r !== 'object') {
  r = { ok: false, error: 'อ่านผลลัพธ์สคริปต์ไม่ได้', raw: JSON.stringify(j).slice(0, 400) };
}

const ok = r.ok === true;
const step = r.step || (ok ? 'done' : 'unknown');
const posted = r.posted === true;
const tk = r.tiktok;
const tiktokUrl = (tk && typeof tk === 'object') ? (tk.profile || null) : (typeof tk === 'string' ? tk : null);
const posts = (tk && typeof tk === 'object' && typeof tk.posts !== 'undefined') ? tk.posts : null;

const days = Math.min(90, Math.max(1, Number(req.days) || Number($env.AUTOPILOT_REGISTER_DAYS) || 7));

return [{ json: {
  ok, step, posted,
  videoFile: r.videoFile || null,
  videoBytes: r.videoBytes || null,
  captionLen: r.captionLen || 0,
  promptLen: r.promptLen || 0,
  promptHead: r.promptHead || null,
  posts, tiktok: tiktokUrl,
  error: r.error || null,
  days, limit: 200,
  conversation: String(req.conversation || $env.AUTOPILOT_CONVERSATION || '6acaccdd-9db8-83ec-a810-87a3fb36a004'),
  detail: ok
    ? (posted ? 'สร้างวิดีโอด้วย Flow + โพสต์ขึ้น TikTok แล้ว' : 'สร้างวิดีโอแล้ว แต่ยังไม่กดโพสต์ (หรือโพสต์ไม่ยืนยัน)')
    : ('ล้มเหลวขั้น ' + step + ': ' + (r.error || 'ไม่ทราบสาเหตุ'))
} }];

// ประกอบอีเมล HTML: ผลการสร้าง/โพสต์วิดีโอ + รายชื่อผู้สนใจสมัครใหม่จากหน้า /register
const v = $('สรุปผล + ตั้งค่าคิวรี').first().json;
const reg = $input.first().json || {};
const list = Array.isArray(reg.registrants) ? reg.registrants : [];
const days = Number(v.days) || 7;

const esc = (s) => String(s === null || s === undefined ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const thDate = (iso) => {
  try {
    const d = new Date(iso);
    return d.toLocaleString('th-TH', { timeZone: 'Asia/Bangkok', day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
  } catch (e) { return String(iso || ''); }
};

const badge = (txt, color) =>
  '<span style="display:inline-block;padding:2px 8px;border-radius:10px;background:' + color + ';color:#fff;font-size:12px">' + esc(txt) + '</span>';

const statusColor = v.ok ? (v.posted ? '#138a36' : '#b26a00') : '#c0392b';
const statusText = v.ok ? (v.posted ? 'สำเร็จ + โพสต์ TikTok' : 'สร้างวิดีโอแล้ว (ยังไม่ยืนยันโพสต์)') : 'ล้มเหลว';

const rows = list.length
  ? list.map((r, i) => {
      const lvl = Number(r.level) === 0 ? badge('ผู้สนใจ (rank 0)', '#0b6ea8') : badge('rank ' + r.level, '#6b7280');
      return '<tr style="background:' + (i % 2 ? '#f8fafc' : '#fff') + '">' +
        '<td style="padding:6px 8px;border-bottom:1px solid #e5e7eb">' + esc(r.name || '-') + '</td>' +
        '<td style="padding:6px 8px;border-bottom:1px solid #e5e7eb"><a href="mailto:' + esc(r.email) + '">' + esc(r.email) + '</a></td>' +
        '<td style="padding:6px 8px;border-bottom:1px solid #e5e7eb;white-space:nowrap">' + esc(r.phone || '-') + '</td>' +
        '<td style="padding:6px 8px;border-bottom:1px solid #e5e7eb;white-space:nowrap">' + esc(thDate(r.createdAt)) + '</td>' +
        '<td style="padding:6px 8px;border-bottom:1px solid #e5e7eb">' + esc(r.sponsor || '-') + '</td>' +
        '<td style="padding:6px 8px;border-bottom:1px solid #e5e7eb">' + lvl + '</td></tr>';
    }).join('')
  : '<tr><td colspan="6" style="padding:10px;color:#6b7280">— ยังไม่มีผู้สมัครใหม่ในช่วง ' + days + ' วันที่ผ่านมา —</td></tr>';

const byDay = Object.keys(reg.byDay || {}).sort().reverse().slice(0, 10)
  .map(d => esc(d) + ': ' + reg.byDay[d]).join(' · ') || '-';

const tr = (k, val) => '<tr><td style="padding:4px 10px 4px 0;color:#6b7280;white-space:nowrap">' + esc(k) + '</td><td style="padding:4px 0">' + val + '</td></tr>';

const html = '' +
'<div style="font-family:system-ui,-apple-system,Segoe UI,sans-serif;line-height:1.65;color:#111827;max-width:760px">' +
  '<h2 style="margin:0 0 4px">📣 AI Content Autopilot — รายงานผล</h2>' +
  '<div style="color:#6b7280;font-size:13px;margin-bottom:14px">' + esc(thDate(new Date().toISOString())) +
    ' · ChatGPT (' + esc(String(v.conversation).slice(0, 12)) + '…) → Google Flow → TikTok @aka989._</div>' +

  '<div style="border:1px solid #e5e7eb;border-radius:10px;padding:12px 14px;margin-bottom:16px">' +
    '<h3 style="margin:0 0 8px;font-size:15px">1) วิดีโอ + การโพสต์ TikTok ' + badge(statusText, statusColor) + '</h3>' +
    '<table style="border-collapse:collapse;font-size:13px">' +
      tr('ขั้นตอนสุดท้าย', esc(v.step)) +
      tr('พรอมต์จาก ChatGPT', v.promptLen ? (v.promptLen + ' ตัวอักษร') : '—') +
      tr('ไฟล์วิดีโอ', v.videoFile ? esc(v.videoFile.split(/[\\/]/).pop()) : '— (ยังไม่ได้สร้าง/ดาวน์โหลด)') +
      (v.videoBytes ? tr('ขนาดไฟล์', (Math.round(v.videoBytes / 1048576 * 10) / 10) + ' MB') : '') +
      tr('ความยาวคำอธิบาย', v.captionLen ? (v.captionLen + ' ตัวอักษร') : '—') +
      tr('โพสต์บน TikTok', v.posted ? 'ยืนยันแล้ว' : 'ยังไม่ยืนยัน') +
      (v.posts !== null ? tr('จำนวนโพสต์ในบัญชี', String(v.posts)) : '') +
      (v.error ? tr('ข้อผิดพลาด', '<span style="color:#c0392b">' + esc(v.error) + '</span>') : '') +
    '</table>' +
  '</div>' +

  '<div style="border:1px solid #e5e7eb;border-radius:10px;padding:12px 14px;margin-bottom:16px">' +
    '<h3 style="margin:0 0 8px;font-size:15px">2) ผู้สนใจสมัครผ่านหน้า /register ' +
      badge(String(list.length) + ' ราย / ' + days + ' วัน', '#0b6ea8') + '</h3>' +
    '<div style="color:#6b7280;font-size:12px;margin-bottom:8px">' + esc(byDay) + '</div>' +
    '<table style="border-collapse:collapse;font-size:13px;width:100%">' +
      '<tr style="background:#f1f5f9;text-align:left">' +
        '<th style="padding:6px 8px">ชื่อ</th><th style="padding:6px 8px">อีเมล</th>' +
        '<th style="padding:6px 8px">โทร</th><th style="padding:6px 8px">สมัครเมื่อ</th>' +
        '<th style="padding:6px 8px">ผู้แนะนำ</th><th style="padding:6px 8px">ระดับ</th></tr>' +
      rows +
    '</table>' +
    '<div style="color:#6b7280;font-size:12px;margin-top:8px">ที่มา: ทะเบียนจริงของแอป (ตาราง user) — อ่านอย่างเดียวจากเครื่องที่รัน n8n</div>' +
  '</div>' +

  '<div style="font-size:13px">' +
    '🔗 <a href="' + REGISTER_URL + '">หน้าสมัคร /register</a> · ' +
    '<a href="' + TIKTOK_URL + '">โปรไฟล์ TikTok @aka989._</a>' +
  '</div>' +
  '<div style="color:#9ca3af;font-size:12px;margin-top:10px">ระบบอัตโนมัติ n8n · AI Content Autopilot 02 · อีเมลนี้ส่งถึงผู้ดูแลระบบเท่านั้น</div>' +
'</div>';

const subject = (v.ok ? (v.posted ? '✅ ' : '⚠️ ') : '❌ ') + 'AI Content Autopilot · ' + v.step +
  ' · ผู้สนใจใหม่ ' + list.length + ' ราย (' + days + ' วัน)';

return [{ json: { subject, html, kind: 'info', stage: v.step, ok: v.ok, posted: v.posted,
                  registrants: list.length, detail: v.detail, error: v.error } }];
